'use client';

import { FANOUT_RESTING, FANOUT_STORY_GRID } from '@/components/visuals/stories/fanout-story-scenes';
import { DotStory, type LoadDotStory } from '@/components/visuals/dot-engine/dot-story';

const loadFanoutStory: LoadDotStory = async (stage) => {
	const { createFanoutStoryPlayer } = await import('@/components/visuals/stories/fanout-story-player');
	return createFanoutStoryPlayer(stage);
};

export function FanoutStory({ className }: { className?: string }) {
	return <DotStory grid={FANOUT_STORY_GRID} resting={FANOUT_RESTING} load={loadFanoutStory} className={className} />;
}

import { BRANCH_ROW, DROP, FANNED_OUT, FANOUT_LABEL, FANOUT_STORY_GRID, PARALLEL_LABEL, QUESTION, QUESTION_LABEL, QUESTION_ONLY, RESULT_ROWS, SEARCHES, SEARCH_FIELD, SEARCH_QUERIES, STEM } from '@/components/visuals/stories/fanout-story-scenes';
import { fadedInAt, paintRevealed, revealSchedule } from '@/components/visuals/stories/story-reveal';
import { createBeatStoryPlayer, typingSeconds } from '@/components/visuals/dot-engine/dot-story-beats';
import type { DotStoryPlayer, DotStoryStage } from '@/components/visuals/dot-engine/dot-story-player';

const CLEAR_SECONDS = 0.8;
const TYPING = { startsAt: 0.4, charactersPerSecond: 14 };
const TYPED_AT = TYPING.startsAt + typingSeconds(QUESTION, TYPING.charactersPerSecond);
const FANOUT = { startsAt: TYPED_AT + 0.4, secondsPerRow: 0.06, secondsPerColumn: 0.02 };
const BRANCHED_AT = FANOUT.startsAt + (BRANCH_ROW - STEM.top) * FANOUT.secondsPerRow;
const SEARCHES_AT = BRANCHED_AT + 1;
const RESULTS = { startsAt: SEARCHES_AT + 0.7, everyLineSeconds: 0.15, sweepSeconds: 0.4 };
const HOLD_SECONDS = RESULTS.startsAt + RESULT_ROWS.length * RESULTS.everyLineSeconds + RESULTS.sweepSeconds + 2.6;

const { rows } = FANOUT_STORY_GRID;
const branchedAt = (column: number) => BRANCHED_AT + Math.abs(column - STEM.column) * FANOUT.secondsPerColumn;

const FANNED_OUT_AT = revealSchedule(FANOUT_STORY_GRID, (column, row) => {
	if (row < STEM.top) return 0;
	if (row <= BRANCH_ROW) return row === BRANCH_ROW ? branchedAt(column) : FANOUT.startsAt + (row - STEM.top) * FANOUT.secondsPerRow;
	if (row <= DROP.bottom) return branchedAt(column) + (row - BRANCH_ROW) * FANOUT.secondsPerRow;
	if (row <= SEARCH_FIELD.bottom) return SEARCHES_AT + (row - SEARCH_FIELD.top) * FANOUT.secondsPerRow;
	const search = SEARCHES.find(({ left, right }) => column >= left && column <= right) ?? SEARCHES[0];
	return RESULTS.startsAt + RESULT_ROWS.indexOf(row) * RESULTS.everyLineSeconds + ((column - search.left) / (search.right - search.left)) * RESULTS.sweepSeconds;
});

export function createFanoutStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
	return createBeatStoryPlayer(stage, {
		grid: FANOUT_STORY_GRID,
		resting: { beat: 0, heldSeconds: HOLD_SECONDS },
		beats: [
			{
				picture: QUESTION_ONLY,
				departure: FANNED_OUT,
				arrival: { kind: 'builds', seconds: CLEAR_SECONDS, order: (_, row) => 1 - row / rows },
				holdSeconds: HOLD_SECONDS,
				animate: (states, heldSeconds) => paintRevealed(states, FANNED_OUT.states, FANNED_OUT_AT, heldSeconds),
				write(pen, heldSeconds) {
					pen.text(QUESTION_LABEL);
					pen.type(QUESTION, heldSeconds, TYPING);
					pen.text(FANOUT_LABEL, fadedInAt(heldSeconds, FANOUT.startsAt));
					SEARCH_QUERIES.forEach((query) => pen.text(query, fadedInAt(heldSeconds, SEARCHES_AT + 0.2)));
					pen.text(PARALLEL_LABEL, fadedInAt(heldSeconds, RESULTS.startsAt + 0.3));
				},
			},
		],
	});
}

import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/visuals/dot-engine/dot-morph-dots';
import { pictureOf } from '@/components/visuals/dot-engine/dot-story-beats';
import { clear, rectangle, stack, type DotBox, type DotPainter } from '@/components/visuals/dot-engine/dot-story-cells';
import type { DotStoryText } from '@/components/visuals/dot-engine/dot-story-player';

export const FANOUT_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };

const { pitch: PITCH } = FANOUT_STORY_GRID;
const x = (column: number) => column * PITCH;
// Doto sits a third of its size below the middle of the row it is set on.
const baselineOn = (row: number, size: number) => (row + 0.5) * PITCH + size / 3;

const QUESTION_FIELD: DotBox = { left: 3, right: 54, top: 4, bottom: 9 };
export const STEM = { column: 28, top: 10, bottom: 14 };
export const BRANCH_ROW = 15;
export const DROP = { top: 16, bottom: 18 };
export const SEARCHES = [
	{ left: 2, right: 18, query: 'agent citations' },
	{ left: 20, right: 36, query: 'llm grounding' },
	{ left: 39, right: 55, query: 'source links' },
];
export const SEARCH_FIELD = { top: 19, bottom: 23 };
export const RESULT_ROWS = [26, 28, 30];
const RANK_TAB = 4;
const RESULT_ENDS = [1, 4, 2];

const centerOf = ({ left, right }: { left: number; right: number }) => Math.round((left + right) / 2);
const BRANCH = { left: centerOf(SEARCHES[0]), right: centerOf(SEARCHES[SEARCHES.length - 1]) };

const questionField = rectangle(QUESTION_FIELD, clear);

const fanout: DotPainter = (column, row) => {
	if (column === STEM.column && row >= STEM.top && row <= STEM.bottom) return DOT_HOLLOW;
	if (row === BRANCH_ROW && column === STEM.column) return DOT_FILLED;
	if (row === BRANCH_ROW && column >= BRANCH.left && column <= BRANCH.right) return DOT_HOLLOW;
	if (row >= DROP.top && row <= DROP.bottom && SEARCHES.some((search) => centerOf(search) === column)) return DOT_HOLLOW;
	return DOT_ABSENT;
};

const searchFields = stack(...SEARCHES.map(({ left, right }) => rectangle({ left, right, top: SEARCH_FIELD.top, bottom: SEARCH_FIELD.bottom }, clear)));

const searchResults: DotPainter = (column, row) => {
	const line = RESULT_ROWS.indexOf(row);
	const search = SEARCHES.find(({ left, right }) => column > left && column < right);
	if (line < 0 || !search || column > search.right - RESULT_ENDS[line]) return DOT_ABSENT;
	return column <= search.left + RANK_TAB ? DOT_FILLED : DOT_HOLLOW;
};

export const QUESTION_ONLY = pictureOf(FANOUT_STORY_GRID, questionField);
export const FANNED_OUT = pictureOf(FANOUT_STORY_GRID, stack(questionField, fanout, searchFields, searchResults));

export const QUESTION_LABEL: DotStoryText = { text: 'query', x: x(QUESTION_FIELD.left + 1), y: baselineOn(2, 12), size: 12, weight: 700, muted: true };
export const QUESTION: DotStoryText = { text: 'how do agents cite web sources?', x: x(QUESTION_FIELD.left + 3), y: baselineOn(6.5, 15), size: 15, weight: 700 };
export const SEARCH_QUERIES: DotStoryText[] = SEARCHES.map(({ left, query }) => ({ text: query, x: x(left + 2), y: baselineOn(21, 12), size: 12, weight: 700 }));
export const FANOUT_LABEL: DotStoryText = { text: 'queryFanout: true', x: x(3), y: baselineOn(34.5, 12), size: 12, weight: 700, muted: true };
export const PARALLEL_LABEL: DotStoryText = { text: '3 searches in parallel', x: x(55), y: baselineOn(34.5, 12), size: 12, weight: 700, muted: true, anchor: 'end' };

export const FANOUT_RESTING = { ...FANNED_OUT, texts: [QUESTION_LABEL, QUESTION, ...SEARCH_QUERIES, FANOUT_LABEL, PARALLEL_LABEL] };
